import itertools
L=np.log(sigma); le=np.log(eps); one=np.ones(300)
cols={'lT':np.log(T),'iT':1/T,'le':le,'le/T':le/T,'le2':le**2,'T':T,'T2':T**2,'le2/T':le**2/T,'le3':le**3,'le*lT':le*np.log(T),'eps':eps,'eps/T':eps/T,'eps*T':eps*T,'le2*T':le**2*T,'iT2':1/T**2,'le/T2':le/T**2}
names=list(cols)
for k in range(2,6):
    best=None
    for comb in itertools.combinations(names,k):
        A=np.column_stack([one]+[cols[c] for c in comb])
        c=np.linalg.lstsq(A,L,rcond=None)[0]; s=np.std(L-A@c)
        if best is None or s<best[0]: best=(s,comb,c)
